def romanToInt_replace(s):
    # 替换特例法：把 6 个减法特例展开成纯加法后统一累加
    reps = {"IV": "IIII", "IX": "VIIII", "XL": "XXXX",
            "XC": "LXXXX", "CD": "CCCC", "CM": "DCCCC"}
    for a, b in reps.items():
        s = s.replace(a, b)
    vals = dict(I=1, V=5, X=10, L=50, C=100, D=500, M=1000)
    return sum(vals[ch] for ch in s)

