class Solution {
public:
    int romanToInt(string s) {
        // 符号 -> 数值 的哈希映射表，7 个基本符号
        unordered_map<char, int> vals = {{'I', 1}, {'V', 5}, {'X', 10},
                                         {'L', 50}, {'C', 100}, {'D', 500}, {'M', 1000}};
        int ans = 0, prev = 0;      // prev 记录右边一个字符的数值
        // 从右往左遍历：小值在大值左边 => 减法；否则加法
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            int v = vals[s[i]];
            if (v < prev) ans -= v; // 触发特例：IV、IX、XL、XC、CD、CM
            else ans += v;
            prev = v;
        }
        return ans;
    }
};

