def longestCommonPrefix_horizontal(strs):
    # 横向两两归并：prefix 与每个串重新求 LCP，单调不增
    def lcp_two(a, b):
        i = 0
        while i < len(a) and i < len(b) and a[i] == b[i]:
            i += 1                  # 越界判断必须先于字符比较
        return a[:i]

    prefix = strs[0]
    for s in strs[1:]:
        prefix = lcp_two(prefix, s)  # LCP 结合律保证正确
        if not prefix:               # 提前剪枝
            break
    return prefix

def longestCommonPrefix(strs):
    # 纵向按列扫描：以第一个串为基准，逐列比较所有串
    for i, ch in enumerate(strs[0]):
        for s in strs[1:]:
            # 任一串已到头，或该列字符不一致 => 公共前缀止于 i
            if i == len(s) or s[i] != ch:
                return strs[0][:i]
    # 循环走完说明第一个串本身就是所有串的公共前缀
    return strs[0]

