    const string& base = strs[0];
    for (int i = 0; i < (int)base.size(); ++i) {
        for (int j = 1; j < (int)strs.size(); ++j) {
            // 任一串已到头，或该列字符不一致 => 公共前缀到此为止
            if (i == (int)strs[j].size() || strs[j][i] != base[i]) {
                return base.substr(0, i);
            }
        }
    }
    return base;    // 第一个串本身就是所有串的公共前缀
}

