class Solution {
public:
    string reverseWords(string s) {
        int n = (int)s.size(), l = 0, r = 0;   // l: 下一个写入位置；r: 读指针
        // 第一步：压缩空格——单词之间保留且仅保留一个空格
        while (r < n) {
            while (r < n && s[r] == ' ') ++r;  // 跳过连续空格
            if (r == n) break;
            if (l > 0) s[l++] = ' ';           // 不是第一个单词，先补一个分隔空格
            while (r < n && s[r] != ' ') s[l++] = s[r++];  // 拷贝整个单词
        }
        s.resize(l);           // 截掉压缩后残留的尾部
        // 第二步：整体反转，单词顺序颠倒
        reverse(s.begin(), s.end());
        // 第三步：把每个单词内部再反转回来
        int start = 0;
        for (int i = 0; i <= (int)s.size(); ++i) {
            if (i == (int)s.size() || s[i] == ' ') {
                reverse(s.begin() + start, s.begin() + i);
                start = i + 1;
            }
        }
        return s;
    }
};

