    string line;
    getline(cin, line);                // 整行读入
    while (!line.empty() && line.back() == '\r') line.pop_back();  // 去掉行尾 \r

    vector<string> words;              // 去多余空格并切词（等价 Python 的 split()）
    string w;
    for (char c : line) {
        if (c == ' ') {
            if (!w.empty()) {          // 单词结束才入列，天然去掉连续空格
                words.push_back(w);
                w.clear();
            }
        } else {
            w += c;
        }
    }
    if (!w.empty()) words.push_back(w);

