class Solution {
    public String reverseWords(String s) {
        char[] chars = s.toCharArray();        // String 不可变，转字符数组模拟原地操作
        int n = chars.length, l = 0, r = 0;    // l: 下一个写入位置；r: 读指针
        // 第一步：压缩空格——单词之间保留且仅保留一个空格
        while (r < n) {
            while (r < n && chars[r] == ' ') r++;  // 跳过连续空格
            if (r == n) break;
            if (l > 0) chars[l++] = ' ';           // 不是第一个单词，先补一个分隔空格
            while (r < n && chars[r] != ' ') chars[l++] = chars[r++];  // 拷贝整个单词
        }
        // 第二步：整体反转 [0, l-1]，单词顺序颠倒
        reverse(chars, 0, l - 1);
        // 第三步：把每个单词内部再反转回来
        int start = 0;
        for (int i = 0; i <= l; i++) {
            if (i == l || chars[i] == ' ') {
                reverse(chars, start, i - 1);
                start = i + 1;
            }
        }
        return new String(chars, 0, l);
    }

    // 反转闭区间 [i, j]
    private void reverse(char[] a, int i, int j) {
        while (i < j) {
            char t = a[i];      // 经典三步交换
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
        }
    }
}

